"""Article-specific editorial source for CC-06 (Civil Code arts. 115-250)."""
from __future__ import annotations


def row(says, means, example, warning, term, definition, *, target=None, terms=None):
    return {
        "target": target,
        "o_que_diz": says,
        "o_que_significa": means,
        "exemplo_pratico": example,
        "atencao": warning,
        "palavras_dificeis": terms or [{"termo": term, "explicacao": definition}],
    }


ROWS = {
    "115": row("A representação pode nascer diretamente da lei ou da vontade da pessoa representada.", "Na representação legal, a norma atribui poderes a alguém para agir por outra pessoa. Na voluntária, o próprio interessado concede esses poderes, normalmente por mandato. Em ambos os casos, é indispensável identificar a origem e os limites da autorização.", "Os pais representam o filho nas hipóteses legais; um proprietário também pode nomear procurador para vender determinado bem.", "Representação não transfere a titularidade do direito. O representante atua em nome alheio e deve permanecer dentro dos poderes recebidos.", "Representação", "atuação juridicamente reconhecida de uma pessoa em nome de outra"),
    "116": row("A declaração feita pelo representante dentro dos poderes recebidos produz efeitos diretamente para o representado.", "Quando age validamente em nome de outra pessoa, o representante não se torna parte econômica do negócio: direitos e obrigações recaem sobre o representado. Esse efeito direto depende de atuação dentro do poder legal ou voluntariamente conferido.", "Procurador autorizado assina contrato de locação em nome do proprietário; o proprietário passa a ser locador.", "Se o representante ultrapassar seus poderes, não se aplica automaticamente o efeito previsto neste artigo; devem ser examinadas responsabilidade, ratificação e regras próprias.", "Representado", "pessoa em cujo nome o representante pratica o ato"),
    "117": row("Em regra, é anulável o negócio em que o representante contrata consigo mesmo, direta ou indiretamente, salvo autorização da lei ou do representado.", "O autocontrato cria risco de favorecimento porque a mesma pessoa ocupa posições contrapostas. A proibição alcança também o negócio feito por quem recebeu poderes em subestabelecimento. A autorização válida afasta a regra geral de anulabilidade.", "Procurador encarregado de vender um imóvel compra o bem para si sem permissão específica do proprietário.", "O negócio não é automaticamente inexistente ou nulo: a consequência indicada é anulabilidade, sujeita às regras e aos prazos correspondentes.", "Autocontrato", "negócio em que a mesma pessoa atua nos dois lados da relação representativa"),
    "118": row("O representante deve demonstrar a terceiros sua condição e a extensão dos poderes que recebeu.", "Quem negocia em nome alheio precisa tornar verificável o título de representação. Se não comprovar os poderes e os exceder, poderá responder pessoalmente pelos atos praticados além da autorização.", "Antes de assinar a venda, o procurador apresenta a procuração que limita preço e forma de pagamento.", "A simples afirmação de que se representa alguém não basta quando o terceiro exige prova. Também é necessário conferir prazo, objeto e eventuais restrições do instrumento.", "Extensão dos poderes", "conjunto de atos e limites abrangidos pela autorização representativa"),
    "119": row("O negócio feito em conflito de interesses pode ser anulado quando o terceiro sabia ou deveria saber do conflito.", "A proteção depende de incompatibilidade entre o interesse do representante e o do representado, somada à ciência real ou exigível da outra parte. O pedido de anulação está sujeito a decadência de cento e oitenta dias, contados da conclusão do negócio ou do fim da incapacidade.", "Representante vende bem do representado a empresa que controla, e a compradora conhece a situação.", "Conflito de interesses não se presume apenas porque o resultado foi desfavorável. Devem ser demonstrados o conflito e o conhecimento exigido pelo artigo.", "Decadência", "perda do direito de pedir determinada medida após o prazo legal"),
    "120": row("A representação legal segue as normas específicas aplicáveis; a voluntária observa as regras da Parte Especial do Código.", "O artigo encaminha cada modalidade ao seu regime próprio. Poder familiar, tutela ou curatela não se confundem com mandato concedido por vontade do interessado. Fonte, alcance, prestação de contas e extinção dos poderes podem variar.", "Para saber os poderes de um tutor consulta-se a disciplina da tutela; para um procurador, as regras do mandato.", "Não se devem transportar automaticamente regras do mandato para toda representação legal. A norma específica da relação tem prioridade.", "Representação voluntária", "representação criada por manifestação de vontade do interessado"),
    "121": row("Condição é cláusula voluntária que faz os efeitos do negócio dependerem de acontecimento futuro e incerto.", "O evento ainda não ocorreu e pode ou não acontecer. Isso distingue condição de termo, que se refere a acontecimento futuro certo. A cláusula deve resultar da vontade das partes, e não de requisito imposto diretamente pela lei.", "Doação prevê que o bem será transferido se o beneficiário concluir determinado curso.", "Nem toda referência ao futuro é condição. É preciso verificar se há incerteza do evento e se os efeitos do negócio foram realmente subordinados a ele.", "Condição", "cláusula que vincula efeitos do negócio a evento futuro e incerto"),
    "122": row("Condições são admitidas quando respeitam lei, ordem pública e bons costumes, mas não podem eliminar todo efeito do negócio nem deixá-lo ao puro arbítrio de uma parte.", "A autonomia privada permite modelar efeitos futuros, porém não legitima cláusula ilícita, contraditória com valores obrigatórios ou meramente potestativa. A condição deve conservar conteúdo juridicamente controlável.", "Contrato não pode depender apenas de o devedor decidir, sem qualquer parâmetro, se deseja cumprir.", "Condição ligada à conduta de uma parte não é sempre proibida. O defeito está no puro arbítrio, sem fator objetivo ou compromisso juridicamente apreciável.", "Condição potestativa", "condição relacionada à vontade de uma parte; será vedada quando submetida ao seu puro arbítrio"),
    "123": row("Invalidam o negócio as condições suspensivas impossíveis, as condições ilícitas ou voltadas a ato ilícito e as incompreensíveis ou contraditórias.", "Esses defeitos atingem o negócio subordinado à condição. A impossibilidade física ou jurídica recebe aqui tratamento específico quando a condição é suspensiva, pois impede a aquisição do direito pretendido.", "Promessa condicionada a fato fisicamente impossível não produz validamente o efeito suspenso.", "O artigo trata de invalidação do negócio, não apenas de desconsideração da cláusula. Condições resolutivas impossíveis seguem regra diferente no artigo seguinte.", "Condição suspensiva", "cláusula que impede a aquisição do direito enquanto o evento não ocorre"),
    "124": row("A condição resolutiva impossível e a condição de não fazer algo impossível são tratadas como inexistentes.", "Nessas hipóteses, elimina-se a condição sem invalidar, por esse motivo, o negócio. O resultado difere da condição suspensiva impossível prevista no artigo anterior.", "Contrato prevê sua extinção se ocorrer evento fisicamente impossível; essa cláusula resolutiva é desconsiderada.", "A solução depende da espécie de condição. Não se deve aplicar esta regra a condição ilícita nem confundir inexistência da cláusula com inexistência do negócio inteiro.", "Condição resolutiva", "cláusula que extingue o direito quando o evento futuro e incerto acontece"),
    "125": row("Enquanto a condição suspensiva não ocorrer, o direito pretendido pelo negócio ainda não é adquirido.", "O negócio existe, mas a aquisição do direito permanece pendente do evento futuro e incerto. Antes do implemento, há expectativa juridicamente protegida, não o direito definitivo que a cláusula condicionou.", "Comprador só adquirirá determinado direito se obtiver licença prevista como condição suspensiva.", "A pendência não autoriza destruir a expectativa da outra parte. O titular eventual pode praticar atos conservatórios conforme o art. 130.", "Implemento da condição", "ocorrência do evento previsto na cláusula condicional"),
    "126": row("Disposições posteriores sobre a coisa, feitas enquanto pende condição suspensiva, perdem eficácia quando incompatíveis com o direito que surge após a condição.", "A regra protege quem adquire o direito condicionado. O titular provisório não pode frustrar o efeito futuro mediante ato incompatível praticado durante a pendência.", "Bem prometido sob condição é depois transferido de forma incompatível; cumprida a condição, examina-se a ineficácia do ato posterior.", "A incompatibilidade precisa ser demonstrada. O artigo não declara sem efeito toda disposição posterior nem dispensa a análise de terceiros e de regras registrais.", "Direito eventual", "posição jurídica dependente da realização de condição ainda pendente"),
    "127": row("Na condição resolutiva, o negócio e o direito produzem efeitos desde o início, até que o evento previsto aconteça.", "Diferentemente da condição suspensiva, o titular pode exercer imediatamente o direito. A ocorrência futura e incerta atua para extinguir a situação jurídica.", "Contrato vigora desde a assinatura, mas será resolvido se a licença essencial for definitivamente cancelada.", "O direito atual não é definitivo enquanto a condição estiver pendente. Seu exercício deve respeitar boa-fé e os efeitos próprios da eventual resolução.", "Resolução", "extinção dos efeitos do negócio em razão de causa prevista na lei ou no próprio negócio"),
    "128": row("Realizada a condição resolutiva, extingue-se o direito; em relações continuadas, atos anteriores compatíveis e praticados de boa-fé podem ser preservados.", "A resolução normalmente opera sobre o direito condicionado, mas a lei protege a estabilidade de prestações periódicas já executadas quando a natureza da condição e a boa-fé justificam.", "Encerrada locação por evento resolutivo, pagamentos e usos regulares anteriores não são automaticamente desfeitos.", "As partes podem estabelecer solução diferente dentro dos limites legais. A preservação dos atos anteriores exige compatibilidade com a natureza da condição e boa-fé.", "Execução continuada", "relação cujos efeitos se prolongam ou se repetem ao longo do tempo"),
    "129": row("A lei neutraliza a interferência maliciosa de quem impede ou provoca a condição em benefício próprio.", "Se a parte desfavorecida pela ocorrência impede deslealmente o evento, a condição é considerada realizada. Se quem seria beneficiado a provoca maliciosamente, ela é tratada como não ocorrida. A regra protege boa-fé e impede vantagem obtida por manipulação.", "Devedor sabota vistoria necessária para impedir a condição que liberaria pagamento ao credor.", "É indispensável demonstrar atuação maliciosa e nexo com o evento. A mera dificuldade ou cooperação legítima não produz automaticamente a ficção legal.", "Ficção jurídica", "tratamento legal de um fato como ocorrido ou não ocorrido para produzir determinado efeito"),
    "130": row("O titular de direito sujeito a condição pode praticar medidas destinadas a conservá-lo.", "Embora o direito definitivo ainda dependa da condição ou possa ser resolvido, a lei permite providências preventivas contra perda, deterioração ou frustração. A medida deve conservar, não antecipar indevidamente, o exercício pleno.", "Beneficiário pede providência para impedir a destruição do bem enquanto aguarda a condição.", "Atos conservatórios não equivalem a exigir desde logo a prestação condicionada. A adequação depende do risco e da natureza do direito eventual.", "Ato conservatório", "medida voltada a preservar um direito ameaçado sem antecipar seu exercício integral"),
    "131": row("O termo inicial impede o exercício imediato, mas o direito já é adquirido.", "Como o termo corresponde a evento futuro certo, a existência do direito não fica em dúvida; apenas sua exigibilidade ou exercício aguarda a data ou acontecimento fixado.", "Crédito constituído hoje será cobrável somente na data de vencimento prevista.", "Termo inicial não se confunde com condição suspensiva: na condição, o evento é incerto e o direito ainda não foi adquirido.", "Termo inicial", "marco futuro e certo a partir do qual o direito poderá ser exercido"),
    "132": row("A contagem civil exclui o dia inicial e inclui o vencimento, com regras para feriado, metade do mês, meses, anos e horas.", "Salvo norma ou convenção diversa, o prazo termina no dia correspondente ao início; se não houver dia igual, vence no imediatamente seguinte. Vencimento em feriado prorroga-se ao próximo dia útil, e prazos por hora correm minuto a minuto.", "Prazo iniciado no dia 10 começa a ser contado no dia 11 e inclui o último dia.", "Regras processuais, administrativas ou especiais podem adotar contagem diferente. Antes de calcular, identifique a natureza do prazo e a norma aplicável.", "Cômputo do prazo", "método usado para determinar o começo, a duração e o vencimento de um prazo"),
    "133": row("Presume-se que o prazo beneficia o herdeiro no testamento e o devedor no contrato, salvo indicação de benefício do credor ou de ambos.", "A presunção ajuda a decidir quem pode renunciar ao prazo ou antecipar a prestação. O instrumento e as circunstâncias podem mostrar que a proteção foi estabelecida para outra parte ou de forma comum.", "Devedor pode pagar antes do vencimento quando o prazo foi estipulado apenas em seu benefício.", "A presunção não prevalece contra cláusula ou contexto claro. Antecipação também deve respeitar a natureza da prestação e eventual interesse legítimo do credor.", "Benefício do prazo", "vantagem jurídica atribuída a uma ou a ambas as partes pela espera até o vencimento"),
    "134": row("Negócios entre vivos sem prazo podem ser exigidos imediatamente, salvo necessidade de execução em outro lugar ou de tempo para cumprir.", "Na ausência de termo, a regra é exigibilidade desde logo. A própria natureza da prestação pode, contudo, exigir deslocamento ou período razoável, impedindo cobrança instantânea incompatível com o que foi assumido.", "Entrega sem data é exigível, mas transporte a cidade distante demanda tempo material adequado.", "Exigibilidade imediata não significa execução impossível no mesmo instante. Boa-fé e características concretas da prestação orientam o tempo necessário.", "Exigibilidade", "possibilidade jurídica de cobrar o cumprimento de uma obrigação"),
    "135": row("As regras de condição suspensiva e resolutiva aplicam-se, quando compatíveis, aos termos inicial e final.", "O termo inicial aproxima-se da condição suspensiva quanto ao adiamento do exercício; o termo final aproxima-se da resolutiva quanto ao encerramento de efeitos. A aplicação é adaptada porque o termo é futuro e certo, enquanto a condição é incerta.", "Direito com data certa de término segue, no que couber, efeitos semelhantes aos da condição resolutiva.", "A remissão não apaga a diferença entre termo e condição. Só se transportam regras compatíveis com a certeza do evento temporal.", "Termo final", "marco futuro e certo que encerra os efeitos de um direito ou negócio"),
    "136": row("O encargo normalmente não impede adquirir nem exercer o direito, salvo se o disponente o tiver imposto expressamente como condição suspensiva.", "Encargo é uma obrigação atribuída ao beneficiário de uma liberalidade. Em regra, ele recebe o direito desde logo e fica obrigado a cumprir a finalidade; excepcionalmente, a redação pode fazer do cumprimento requisito para adquirir o direito.", "Pessoa recebe doação com obrigação de conservar determinado bem cultural.", "Não basta chamar uma cláusula de encargo ou condição. É necessário interpretar se ela apenas impõe dever ou realmente suspende a aquisição.", "Encargo", "dever imposto ao beneficiário de uma liberalidade"),
    "137": row("Encargo ilícito ou impossível é desconsiderado, mas invalida a liberalidade quando foi seu motivo determinante.", "A regra busca preservar o negócio retirando o encargo defeituoso. Porém, se a finalidade ilícita ou impossível foi essencial para a concessão do benefício, não há razão para manter a liberalidade.", "Doação impõe tarefa impossível sem ser essencial; o encargo cai e a doação pode subsistir.", "A solução exige apurar a importância do encargo para o disponente. Não se presume motivo determinante apenas porque a cláusula foi escrita.", "Liberalidade", "atribuição gratuita de vantagem patrimonial, como doação ou legado"),
    "138": row("Erro substancial perceptível por pessoa normalmente diligente pode tornar o negócio anulável.", "O erro precisa atingir aspecto relevante da manifestação de vontade e ser objetivamente reconhecível nas circunstâncias. Pequeno engano sem influência decisiva não basta. A consequência é anulabilidade, não nulidade automática.", "Comprador adquire obra acreditando, por erro essencial perceptível, tratar-se de original de determinado autor.", "A análise considera a relevância do erro e sua cognoscibilidade. Descuido puramente individual e irrelevante pode não autorizar anulação.", "Erro substancial", "falsa percepção essencial que influencia de modo decisivo a celebração do negócio"),
    "139": row("O erro é substancial quando recai sobre natureza ou objeto essencial do negócio, pessoa decisiva ou motivo jurídico principal que não represente recusa à lei.", "O artigo delimita erros capazes de afetar a validade. A identidade ou qualidade da pessoa só importa quando influenciou relevantemente a decisão. Erro de direito pode contar se foi motivo único ou principal, sem servir para ignorar a lei.", "Doação é feita à pessoa errada quando a identidade do beneficiário era decisiva.", "Erro sobre aspecto secundário não se torna substancial apenas porque gerou arrependimento. É necessário vínculo relevante com a vontade declarada.", "Erro de direito", "compreensão equivocada sobre norma jurídica que, em hipóteses limitadas, influencia o negócio"),
    "140": row("Motivo falso só afeta a declaração quando foi expressamente apresentado como razão determinante.", "Razões internas normalmente não integram o negócio. Para que o falso motivo vicie a vontade, ele deve ter sido exteriorizado e colocado como fundamento decisivo da declaração.", "Doação declara expressamente que ocorre por fato específico, depois comprovado inexistente.", "Motivo reservado ou apenas presumido não basta. Também é preciso distinguir motivo falso de condição ou de cláusula contratual autônoma.", "Motivo determinante", "razão expressamente indicada como decisiva para realizar o negócio"),
}

ROWS.update({
    "141": row("Erro na transmissão da vontade por mensageiro ou meio intermediário segue as mesmas hipóteses de anulabilidade da declaração direta.", "A interposição de pessoa ou tecnologia não amplia nem reduz os requisitos do erro. É preciso verificar se a divergência transmitida seria juridicamente relevante caso tivesse sido cometida pelo próprio declarante.", "Mensageiro informa preço diferente do autorizado, alterando elemento essencial perceptível do negócio.", "Nem toda falha de comunicação anula o ato. Aplicam-se os critérios de erro substancial e reconhecível, além da análise de responsabilidade pelo meio utilizado.", "Meio interposto", "pessoa ou instrumento usado para transmitir a declaração de vontade"),
    "142": row("Indicação errada de pessoa ou coisa não invalida o negócio quando o contexto permite identificar o destinatário ou objeto pretendido.", "A lei preserva a declaração se a identidade correta resulta das circunstâncias. O erro de nome ou descrição é superável quando não existe dúvida razoável sobre a vontade efetiva.", "Testamento usa apelido impreciso, mas outros dados individualizam inequivocamente o beneficiário.", "Se houver duas interpretações plausíveis ou a identidade for essencial e incerta, a regra de conservação pode não resolver o problema.", "Erro de indicação", "equívoco na designação nominal ou descritiva de pessoa ou coisa"),
    "143": row("Erro meramente aritmético autoriza corrigir o cálculo, sem desfazer o negócio.", "Quando a vontade e os elementos da operação estão corretos, mas a soma, multiplicação ou transposição numérica saiu errada, retifica-se o resultado. A solução conserva o acordo efetivamente formado.", "Contrato registra parcelas corretas, porém totaliza por engano valor superior; o total é corrigido.", "A regra não cobre erro sobre preço, quantidade ou critério de cálculo realmente negociado. Nesses casos pode existir erro substancial ou divergência contratual.", "Erro de cálculo", "falha aritmética na obtenção de um resultado a partir de elementos já definidos"),
    "144": row("O erro não invalida o negócio quando o destinatário aceita executá-lo conforme a vontade real do declarante.", "A oferta de cumprimento correto elimina o prejuízo decorrente da divergência e favorece a conservação do negócio. A adequação deve corresponder efetivamente ao que o declarante pretendia.", "Vendedor percebe que o comprador indicou por engano outro modelo e concorda em entregar o modelo realmente desejado pelo mesmo ajuste.", "A parte não pode impor versão aproximada ou mais onerosa sob pretexto de corrigir o erro. A conformidade com a vontade real precisa ser demonstrável.", "Conservação do negócio", "preferência por manter o ato quando o defeito pode ser superado sem lesar sua finalidade"),
    "145": row("Dolo que foi causa da celebração torna o negócio anulável.", "Dolo principal é a manobra intencional que induz a outra parte a contratar quando, sem ela, não teria celebrado o negócio. A consequência é anulabilidade, além de possíveis perdas e danos conforme o caso.", "Vendedor oculta deliberadamente defeito estrutural decisivo para convencer o comprador a adquirir o imóvel.", "É necessário provar conduta enganosa relevante e influência causal. Exagero irrelevante ou simples opinião não configura automaticamente dolo principal.", "Dolo principal", "engano intencional determinante para a celebração do negócio"),
    "146": row("Dolo acidental não anula o negócio, mas obriga o responsável a reparar perdas e danos.", "O dolo é acidental quando o negócio teria sido feito mesmo sem a manobra, embora em condições diferentes. Preserva-se o vínculo e indeniza-se o prejuízo causado pela distorção.", "Comprador adquiriria o bem de qualquer modo, mas pagou mais porque o vendedor falseou uma característica secundária.", "A distinção depende da influência concreta do engano sobre a decisão. Se sem ele não haveria contratação, trata-se de dolo principal.", "Dolo acidental", "engano que altera condições do negócio, mas não determina sua própria existência"),
    "147": row("Silêncio intencional sobre fato desconhecido pela outra parte pode constituir dolo em negócio bilateral quando, sem a omissão, o contrato não seria celebrado.", "A omissão torna-se juridicamente relevante quando havia informação decisiva conscientemente escondida. Exige-se vínculo causal entre o silêncio e a manifestação de vontade.", "Fornecedor sabe de impedimento essencial e o oculta para que a outra parte assine o contrato.", "O artigo não cria dever geral de revelar todo dado. Importam relevância, conhecimento, contexto, boa-fé e o caráter determinante da informação omitida.", "Omissão dolosa", "silêncio intencional sobre informação decisiva que induz a outra parte a contratar"),
    "148": row("Dolo praticado por terceiro permite anulação se o beneficiado sabia ou deveria saber; caso contrário, o negócio subsiste e o terceiro indeniza a vítima.", "A consequência varia conforme o conhecimento da parte favorecida. Ciência real ou exigível aproxima o dolo do próprio contratante; desconhecimento preserva o negócio e concentra a responsabilidade no terceiro enganador.", "Corretor mente para favorecer vendedor que conhece a manobra; o comprador pode pedir anulação.", "Não basta demonstrar o dolo do terceiro. É preciso apurar se a parte beneficiada conhecia ou deveria conhecer a fraude.", "Dolo de terceiro", "engano determinante praticado por pessoa que não é parte direta do negócio"),
    "149": row("O dolo do representante legal limita a responsabilidade do representado ao benefício recebido; no representante convencional, ambos respondem solidariamente.", "A lei diferencia representação imposta pela lei e representação escolhida pelo interessado. No primeiro caso, protege o representado além do proveito obtido; no segundo, atribui solidariedade com quem recebeu poderes voluntariamente.", "Procurador escolhido pelo representado engana a contraparte durante a contratação, gerando responsabilidade solidária por danos.", "O artigo disciplina responsabilidade civil pelo dolo do representante e não elimina outras consequências do vício sobre o negócio.", "Responsabilidade solidária", "possibilidade de cobrar integralmente a dívida de qualquer dos responsáveis"),
    "150": row("Quando ambas as partes agem com dolo, nenhuma pode usar o próprio comportamento para anular o negócio ou pedir indenização.", "A lei impede que quem também participou de manobra desleal obtenha proteção baseada no dolo recíproco. As pretensões entre os participantes ficam neutralizadas nessa matéria.", "Comprador e vendedor trocam informações deliberadamente falsas para obter vantagens um do outro.", "A regra exige dolo de ambos relacionado ao negócio. Não significa validar ilícitos contra terceiros nem afastar sanções de outras naturezas.", "Dolo recíproco", "conduta enganosa praticada por ambas as partes no mesmo negócio"),
    "151": row("Coação vicia a vontade quando provoca temor fundamentado de dano iminente e grave à pessoa, família ou bens.", "A ameaça deve ser suficientemente séria para comprometer a liberdade de decidir. Se atingir pessoa fora da família, o juiz avalia as circunstâncias para verificar relevância equivalente.", "Alguém assina contrato após ameaça concreta e imediata de grave dano ao filho.", "Pressão, insistência ou desconforto não bastam por si. Examinam-se gravidade, iminência, credibilidade e efeito sobre a vítima.", "Coação", "pressão mediante ameaça grave que compromete a liberdade da manifestação de vontade"),
    "152": row("A gravidade da coação é avaliada considerando características da vítima e todas as circunstâncias relevantes.", "A mesma ameaça pode afetar pessoas de maneira diferente. Idade, saúde, condição, temperamento e contexto ajudam a medir se houve temor capaz de viciar a vontade.", "Ameaça dirigida a pessoa fragilizada por doença é examinada levando em conta essa condição concreta.", "A avaliação individualizada não legitima estereótipos. Os fatores legais servem para compreender a capacidade real de resistência no caso.", "Circunstâncias pessoais", "características concretas consideradas para avaliar o impacto da ameaça"),
    "153": row("A ameaça de exercer normalmente um direito e o simples temor de desagradar pessoa respeitada não configuram coação.", "Cobrar legitimamente, propor ação cabível ou exercer prerrogativa dentro de seus limites não vicia a vontade. Reverência, respeito ou receio moral sem ameaça grave também não bastam.", "Credor informa que cobrará judicialmente dívida vencida; isso, sem abuso, não torna coagido o acordo.", "Exercício anormal ou abusivo de um direito pode receber avaliação diferente. Também não se confunde temor reverencial com ameaça concreta feita por autoridade familiar ou religiosa.", "Temor reverencial", "receio de desagradar alguém por respeito ou submissão moral, sem ameaça juridicamente relevante"),
    "154": row("Coação de terceiro vicia o negócio se a parte beneficiada sabia ou deveria saber, respondendo ambos solidariamente pelos danos.", "Quando o contratante aproveita ameaça alheia conhecida ou cognoscível, o vício atinge o negócio e a responsabilidade alcança beneficiado e coator.", "Terceiro ameaça vendedor, e comprador consciente da ameaça aproveita para adquirir o bem por valor reduzido.", "Devem ser comprovados a coação, o benefício e o conhecimento real ou exigível. A simples presença de terceiro não cria solidariedade.", "Coator", "pessoa que pratica a ameaça responsável por restringir a liberdade da vítima"),
    "155": row("Se a coação veio de terceiro sem conhecimento real ou exigível da parte beneficiada, o negócio permanece e o coator responde pelos danos.", "A boa-fé da parte favorecida preserva a contratação. A vítima mantém pretensão indenizatória contra quem realizou a ameaça, embora não obtenha anulação por essa regra.", "Comprador de boa-fé desconhece que terceiro ameaçou o vendedor para forçar a venda.", "A subsistência depende da ausência de conhecimento e de dever de conhecer. Outros defeitos ou ilicitudes podem conduzir a solução diversa.", "Subsistência do negócio", "manutenção da validade e dos efeitos do ato apesar de determinada irregularidade externa"),
    "156": row("Estado de perigo ocorre quando alguém assume obrigação excessivamente onerosa para evitar grave dano conhecido pela outra parte.", "A necessidade urgente de salvar a si ou familiar reduz a liberdade de negociação, e a contraparte tem ciência da situação. Para pessoa fora da família, o juiz avalia o vínculo e as circunstâncias.", "Pessoa aceita pagamento desproporcional para obter auxílio indispensável diante de risco grave conhecido pelo prestador.", "Não basta dificuldade econômica comum. Exigem-se grave dano, urgência, conhecimento da outra parte e onerosidade excessiva.", "Estado de perigo", "vício decorrente de obrigação excessiva assumida para afastar grave dano conhecido pela contraparte"),
    "157": row("Lesão ocorre quando necessidade urgente ou inexperiência leva alguém a aceitar prestação manifestamente desproporcional.", "A desproporção é medida pelos valores existentes no momento da contratação. A anulação pode ser evitada se a parte favorecida completar suficientemente a prestação ou reduzir sua vantagem.", "Pessoa inexperiente vende bem de alto valor por quantia muito inferior, em desequilíbrio manifesto.", "Lesão não exige a situação de grave dano do estado de perigo. Também não decorre de qualquer mau negócio: a desproporção deve ser manifesta e ligada à necessidade ou inexperiência.", "Lesão", "vício causado por desproporção manifesta aproveitada em situação de necessidade ou inexperiência"),
    "158": row("Transmissão gratuita ou perdão de dívida por devedor insolvente pode ser anulado por credores anteriores, inclusive quando a garantia deles se torna insuficiente.", "A fraude contra credores protege o patrimônio que responde pelas dívidas. Nos atos gratuitos, basta que o devedor já seja insolvente ou se torne insolvente com o ato, ainda que ignore a situação.", "Devedor doa seu principal imóvel e fica sem bens suficientes para pagar credores já existentes.", "A legitimidade é dos credores que já existiam quando o ato foi praticado. Credor posterior não se beneficia automaticamente desta regra.", "Credor quirografário", "credor sem garantia real ou preferência especial sobre determinado bem"),
    "159": row("Contrato oneroso do devedor insolvente é anulável quando a insolvência era notória ou deveria ser conhecida pelo outro contratante.", "Como existe contraprestação, a lei exige elemento adicional ligado à ciência do adquirente. Protege-se o terceiro de boa-fé que não tinha motivo para conhecer a insolvência.", "Empresa notoriamente insolvente vende ativo essencial a parceiro que conhece sua situação patrimonial.", "Insolvência isolada não invalida todo contrato oneroso. É necessário provar notoriedade ou motivo concreto para conhecimento pela contraparte.", "Insolvência", "situação em que o patrimônio disponível não basta para satisfazer as dívidas"),
    "160": row("Adquirente que ainda não pagou pode depositar judicialmente o preço para conservar os bens; se o preço foi baixo, deve completar até o valor real.", "O depósito protege credores e permite ao adquirente liberar-se da obrigação sem entregar valor ao devedor insolvente. Todos os interessados devem ser citados.", "Comprador deposita em juízo o preço de mercado antes de pagá-lo ao vendedor insolvente.", "Preço apenas aproximado ao corrente pode ser depositado como contratado; preço inferior exige complementação ao valor real para conservar o bem.", "Depósito judicial", "entrega de valor em juízo para produzir pagamento ou assegurar sua destinação correta"),
    "161": row("A ação por fraude pode ser dirigida ao devedor, à contraparte do negócio fraudulento e a terceiros adquirentes de má-fé.", "O artigo define o polo passivo necessário conforme a circulação do bem. Terceiro posterior só é alcançado por esta regra quando agiu de má-fé.", "Credor demanda devedor e comprador participante da fraude; revenda posterior alcança adquirente que conhecia o esquema.", "A boa-fé do subadquirente importa. A composição processual e os efeitos sobre registros e bens exigem análise do caso concreto.", "Terceiro adquirente", "pessoa que recebe o bem depois do negócio originalmente questionado"),
    "162": row("Credor sem garantia que recebe antecipadamente de devedor insolvente deve devolver o valor ao acervo comum.", "O pagamento antes do vencimento favorece indevidamente um credor em prejuízo dos demais. A reposição recompõe o patrimônio sujeito ao concurso de credores.", "Devedor insolvente antecipa dívida ainda não vencida a um credor, que deve restituir o recebido ao acervo.", "A regra trata de dívida não vencida e credor quirografário. Pagamentos vencidos e preferências legítimas exigem disciplina própria.", "Concurso de credores", "procedimento de distribuição do patrimônio insuficiente entre vários credores"),
    "163": row("Presumem-se fraudulentas as garantias dadas por devedor insolvente a um dos credores.", "Criar hipoteca, penhor ou outra garantia nessa situação altera a igualdade entre credores e concede preferência nova sobre patrimônio já insuficiente. A presunção facilita a impugnação.", "Devedor insolvente oferece imóvel em hipoteca para privilegiar dívida antes sem garantia.", "A norma não confunde garantia preexistente válida com preferência criada durante a insolvência. O momento e a natureza do ato são essenciais.", "Garantia real", "direito que vincula bem específico ao pagamento e pode conferir preferência ao credor"),
    "164": row("Negócios ordinários indispensáveis à atividade econômica ou à subsistência do devedor e da família presumem-se de boa-fé.", "A proteção evita paralisar operações normais necessárias à manutenção do estabelecimento ou da vida familiar. A presunção favorece atos compatíveis com rotina e indispensabilidade.", "Comerciante insolvente compra insumos usuais necessários para manter atividade produtiva mínima.", "Operação extraordinária, artificial ou dispensável não recebe automaticamente a proteção. A presunção pode ser confrontada por prova de fraude.", "Negócio ordinário", "operação habitual e compatível com a manutenção normal da atividade ou subsistência"),
    "165": row("Anulado o negócio fraudulento, o benefício retorna ao patrimônio comum dos credores; se havia apenas preferência indevida, anula-se somente essa preferência.", "A finalidade é recompor o acervo, não entregar diretamente o bem ao credor que ajuizou a ação. A invalidação deve atingir apenas o necessário quando o defeito se limita à garantia preferencial.", "Hipoteca fraudulenta é retirada, e o bem volta a responder sem a preferência criada.", "O resultado beneficia o concurso de credores. A extensão da anulação depende de o negócio transferir patrimônio ou apenas estabelecer preferência.", "Acervo", "conjunto de bens e direitos destinado à satisfação coletiva dos credores"),
})

ROWS.update({
    "166": row("O negócio é nulo nas hipóteses legais de incapacidade absoluta, objeto ilícito, impossível ou indeterminável, motivo ilícito comum, falta de forma ou solenidade essencial, fraude à lei imperativa ou proibição sem outra sanção.", "Nulidade protege interesses relevantes do ordenamento e impede que o negócio produza validamente os efeitos pretendidos. Cada inciso exige identificação precisa; não basta considerar o resultado indesejável.", "Venda com objeto proibido por lei possui objeto ilícito e é nula.", "Nulidade não se confunde com anulabilidade. Negócio nulo não é confirmado pelo tempo, enquanto o anulável depende de iniciativa do interessado e pode ser confirmado.", "Nulidade", "invalidade grave prevista em lei que impede a confirmação do negócio"),
    "167": row("Negócio simulado é nulo, mas o negócio oculto pode subsistir se preencher requisitos de conteúdo e forma.", "Há simulação quando a aparência encobre partes, declarações ou datas não verdadeiras. A lei preserva o ato dissimulado realmente desejado somente se ele próprio for válido, e protege terceiros de boa-fé contra os simuladores.", "Partes aparentam doação a intermediário, mas pretendem venda a outra pessoa; examina-se se o negócio oculto pode valer.", "Descobrir a simulação não valida automaticamente o ato escondido. Forma obrigatória, objeto, capacidade e demais requisitos continuam necessários.", "Negócio dissimulado", "ato verdadeiro ocultado pela aparência de outro negócio"),
    "168": row("Qualquer interessado e, quando competente, o Ministério Público podem alegar nulidade; o juiz deve reconhecê-la se estiver provada.", "Nulidade não depende apenas da vontade das partes. Ao tomar conhecimento do negócio e encontrar o defeito demonstrado, o juiz deve pronunciá-lo e não pode corrigir o vício em nome dos contratantes.", "Em processo sobre contrato com objeto ilícito comprovado, o juiz reconhece a nulidade ainda que as partes pretendam mantê-lo.", "Reconhecimento de nulidade exige prova do defeito e oportunidade processual adequada. O juiz não pode inventar cláusula ou suprir solenidade essencial.", "Pronúncia de ofício", "reconhecimento judicial sem depender de pedido específico da parte quando a lei o impõe"),
    "169": row("Negócio nulo não pode ser confirmado e não se torna válido apenas pelo passar do tempo.", "A gravidade do vício impede convalidação por ratificação das partes ou inércia prolongada. Isso diferencia nulidade de defeitos sanáveis do negócio anulável.", "Partes não transformam contrato de objeto ilícito em válido simplesmente declarando que o confirmam anos depois.", "A regra sobre não convalescer não resolve sozinha todos os efeitos patrimoniais, restituições ou situações de terceiros, que seguem disciplina própria.", "Convalidação", "superação de defeito que permitiria ao ato passar a produzir efeitos válidos"),
    "170": row("Negócio nulo pode converter-se em outro válido se contiver seus requisitos e corresponder à finalidade presumível das partes.", "A conversão conserva o resultado juridicamente possível. Exige que o ato defeituoso reúna substância e forma do negócio substituto e que seja razoável concluir que as partes o teriam querido se conhecessem a nulidade.", "Ato nulo como modalidade solene pode valer como outro negócio menos exigente, se todos os requisitos deste estiverem presentes.", "Conversão não é correção livre pelo juiz. Ela depende de compatibilidade objetiva e da finalidade demonstrada pela relação.", "Conversão substancial", "aproveitamento de negócio inválido como outro negócio válido cujos requisitos já estejam presentes"),
    "171": row("O negócio é anulável por incapacidade relativa ou por erro, dolo, coação, estado de perigo, lesão e fraude contra credores, além de outras previsões legais.", "Anulabilidade protege interesse particular afetado por incapacidade ou vício de vontade e depende de alegação de legitimado. O negócio produz efeitos enquanto não for anulado.", "Contrato assinado sem assistência exigida por pessoa relativamente incapaz pode ser judicialmente anulado.", "A consequência não é nulidade automática. Prazos de decadência, confirmação e efeitos da sentença seguem os artigos seguintes.", "Anulabilidade", "invalidade dependente de iniciativa do interessado e sujeita a confirmação ou prazo decadencial"),
    "172": row("As partes podem confirmar negócio anulável, desde que não prejudiquem direito de terceiro.", "A confirmação elimina o vício disponível e estabiliza o negócio. Como terceiros não participaram da decisão, seus direitos previamente constituídos permanecem protegidos.", "Pessoa que sofreu erro reconhece o problema e confirma conscientemente o contrato, sem afetar garantia de terceiro.", "Somente negócio anulável admite essa confirmação. Negócio nulo segue o art. 169 e não pode ser ratificado.", "Confirmação", "manifestação que mantém negócio anulável e elimina a possibilidade de impugná-lo pelo vício conhecido"),
    "173": row("A confirmação expressa deve identificar a substância do negócio e declarar claramente a vontade de mantê-lo.", "O ato confirmatório precisa permitir saber qual negócio está sendo preservado e que a parte, ciente do defeito, pretende superar a anulabilidade.", "Documento descreve contrato, seu objeto e partes e afirma expressamente que será mantido apesar do vício conhecido.", "Declaração vaga de concordância pode não bastar. A confirmação exige conteúdo suficiente e vontade inequívoca.", "Ato confirmatório", "manifestação posterior destinada a preservar negócio anulável"),
    "174": row("A execução parcial e consciente do negócio anulável pode dispensar confirmação expressa.", "Se o devedor conhece o vício e mesmo assim cumpre voluntariamente parte da obrigação, seu comportamento pode demonstrar intenção de manter o negócio. Trata-se de confirmação tácita.", "Após descobrir erro anulável, comprador paga voluntariamente parcela e prossegue no contrato.", "É indispensável conhecimento do vício. Cumprimento por desconhecimento, coação ou necessidade não revela necessariamente confirmação.", "Confirmação tácita", "manutenção do negócio demonstrada por comportamento incompatível com a intenção de anulá-lo"),
    "175": row("Confirmar expressamente ou executar voluntariamente o negócio anulável extingue ações e defesas fundadas naquele vício.", "A parte que conscientemente mantém o negócio perde os instrumentos para depois impugná-lo pela causa confirmada. A regra produz estabilidade e coerência de comportamento.", "Devedor confirma contrato e depois não pode usar o mesmo erro já superado como defesa contra cobrança.", "A extinção alcança pretensões e exceções relativas ao vício confirmado, não direitos independentes nem direitos de terceiros preservados.", "Exceção", "defesa usada para impedir ou limitar a pretensão apresentada pela outra parte"),
    "176": row("Falta de autorização de terceiro pode ser sanada se a autorização for concedida posteriormente.", "Quando a lei ou o negócio exige consentimento de outra pessoa, a anuência posterior valida o ato anulável. A autorização retroativa deve ser válida e proveniente de quem tinha poder para concedê-la.", "Negócio praticado sem consentimento necessário é posteriormente ratificado pela pessoa autorizante.", "A regra trata de anulabilidade por falta de autorização, não de forma essencial ou proibição absoluta. Direitos de terceiros também precisam ser respeitados.", "Autorização posterior", "consentimento dado depois do ato para sanar a falta existente na celebração"),
    "177": row("Anulabilidade só produz efeito após sentença, não é reconhecida de ofício e beneficia, em regra, apenas quem a alegou.", "O negócio permanece eficaz até decisão judicial. Somente interessados legitimados podem invocar o vício, e o resultado não se estende automaticamente a outros, salvo solidariedade ou indivisibilidade.", "Parte lesada pede anulação; o juiz não a decreta por iniciativa própria em favor de quem permaneceu inerte.", "Essa disciplina é oposta à nulidade do art. 168. É necessário observar legitimidade, prazo e alcance subjetivo da sentença.", "Efeito subjetivo", "limitação das consequências da decisão às pessoas juridicamente alcançadas"),
    "178": row("O prazo geral para anular por coação, demais vícios indicados ou incapacidade é de quatro anos, com marcos iniciais diferentes.", "Na coação, conta-se da cessação; em erro, dolo, fraude, estado de perigo ou lesão, da celebração; para atos de incapazes, do fim da incapacidade. Trata-se de decadência.", "Pessoa coagida dispõe de quatro anos a partir do término efetivo das ameaças para pedir anulação.", "Usar o marco errado pode extinguir o direito. Hipóteses com prazo especial não são substituídas automaticamente por este artigo.", "Prazo decadencial", "período após o qual se perde o direito de pedir a anulação"),
    "179": row("Quando a lei declara o ato anulável sem indicar prazo, aplicam-se dois anos desde sua conclusão.", "O artigo funciona como prazo subsidiário específico da anulabilidade. Só incide se não houver prazo próprio em outra norma.", "Lei qualifica determinado ato como anulável, mas silencia sobre tempo; o interessado conta dois anos da conclusão.", "Não se aplica o prazo de dois anos quando a hipótese está no art. 178 ou possui disciplina especial. Também não é prazo de prescrição.", "Prazo subsidiário", "prazo aplicado apenas na ausência de regra específica para a hipótese"),
    "180": row("Menor entre dezesseis e dezoito anos não pode invocar a idade para escapar da obrigação se a ocultou dolosamente ou se declarou maior.", "A proteção da incapacidade relativa não ampara comportamento enganoso do próprio menor. A regra preserva confiança da contraparte quando houve fraude sobre a idade.", "Adolescente de dezessete anos afirma expressamente ser maior para contratar e depois tenta evitar a obrigação apenas pela idade.", "A exceção exige ocultação dolosa quando perguntado ou declaração de maioridade no ato. Não elimina todas as demais proteções do incapaz.", "Ocultação dolosa", "esconder intencionalmente informação relevante para induzir a outra parte"),
    "181": row("Quem pagou a incapaz em negócio anulado só recupera o valor se provar que o pagamento o beneficiou.", "A regra protege o incapaz contra restituição de quantia que não aproveitou ao seu patrimônio ou necessidades. O ônus de demonstrar o benefício é de quem pede a devolução.", "Contratante prova que valor entregue foi usado para adquirir bem que permaneceu no patrimônio do incapaz.", "Entrega formal do dinheiro não demonstra, sozinha, proveito. Deve haver benefício efetivo e identificável para o incapaz.", "Proveito", "vantagem econômica ou utilidade efetivamente incorporada em favor da pessoa"),
    "182": row("Anulado o negócio, as partes retornam à situação anterior; se a restituição material for impossível, paga-se o equivalente.", "A invalidação busca desfazer os efeitos produzidos e evitar enriquecimento indevido. Cada parte devolve o que recebeu, ou seu valor correspondente quando a devolução não puder ocorrer.", "Venda anulada leva à devolução do bem e do preço; se o bem pereceu, examina-se indenização equivalente.", "Restituição pode envolver frutos, despesas, boa-fé e danos sob outras regras. O artigo fornece o princípio geral do retorno.", "Estado anterior", "situação patrimonial existente antes da celebração do negócio anulado"),
    "183": row("Defeito do documento não invalida necessariamente o negócio se ele puder ser provado por outro meio.", "Instrumento e negócio são planos distintos. Quando a forma documental não é requisito de validade, a perda ou invalidade do papel pode ser suprida por prova legal diferente.", "Contrato de forma livre permanece demonstrável por mensagens e testemunhas apesar de defeito no documento particular.", "Se a lei exige aquele instrumento como forma essencial, outra prova não salva a validade. É preciso distinguir forma para prova e forma constitutiva.", "Instrumento", "documento usado para registrar ou provar a manifestação de vontade"),
    "184": row("Parte válida e separável do negócio pode subsistir; invalidade do principal atinge acessórios, mas defeito do acessório não invalida o principal.", "A conservação parcial respeita a intenção das partes e a autonomia das cláusulas. O vínculo de dependência determina quando a invalidade se propaga.", "Cláusula inválida é retirada e o restante do contrato permanece funcional e coerente.", "Separabilidade não é apenas divisão física do texto. A parte restante deve conservar sentido, finalidade e compatibilidade com a vontade negocial.", "Invalidade parcial", "defeito limitado a parte separável do negócio, preservando-se o restante válido"),
    "185": row("Regras dos negócios jurídicos aplicam-se, quando compatíveis, a outros atos jurídicos lícitos.", "Atos lícitos que produzem efeitos previstos pelo direito, embora não sejam negócios baseados em autorregulação de interesses, podem usar subsidiariamente conceitos de validade, forma e interpretação.", "Notificação lícita pode ser examinada por regras gerais de manifestação de vontade compatíveis com sua natureza.", "A aplicação é apenas no que couber. Não se deve transformar todo ato lícito em contrato nem afastar seu regime específico.", "Ato jurídico lícito", "conduta permitida que produz efeitos reconhecidos pelo ordenamento"),
    "186": row("Comete ato ilícito quem, por ação ou omissão voluntária, negligência ou imprudência, viola direito e causa dano, inclusive moral.", "A responsabilidade aquiliana parte de conduta culposa ou dolosa, violação jurídica, dano e relação causal. O dano não precisa ser exclusivamente patrimonial.", "Motorista age com imprudência, danifica bem de terceiro e deve responder pelas consequências civis.", "O artigo não torna todo dano indenizável automaticamente. Devem ser examinados conduta, culpa quando exigida, nexo causal, dano e eventuais excludentes.", "Nexo causal", "ligação juridicamente relevante entre a conduta e o dano produzido"),
    "187": row("O exercício manifestamente excessivo de um direito, contrário à finalidade econômica ou social, à boa-fé ou aos bons costumes, também é ilícito.", "Ter um direito não autoriza utilizá-lo de modo abusivo. O controle recai sobre a forma de exercício e seus limites objetivos, mesmo quando a faculdade existia em abstrato.", "Proprietário usa prerrogativa apenas para prejudicar vizinho, sem finalidade legítima compatível.", "Abuso não se presume de todo exercício que cause incômodo. O excesso deve ser manifesto e aferido pelos limites legais indicados.", "Abuso de direito", "exercício excessivo de posição jurídica que ultrapassa sua finalidade e limites de boa-fé"),
    "188": row("Legítima defesa, exercício regular de direito e intervenção indispensável para afastar perigo iminente não constituem ilícito nos limites legais.", "A lei exclui a ilicitude de condutas justificadas. No estado de necessidade sobre coisa ou pessoa alheia, a medida deve ser absolutamente necessária e não exceder o indispensável.", "Pessoa quebra porta para retirar alguém de incêndio iminente, usando apenas a força necessária.", "Exclusão de ilicitude não elimina automaticamente toda consequência indenizatória prevista em outras regras. Excesso ou alternativa menos lesiva pode retirar a justificativa.", "Exercício regular", "uso de um direito dentro de sua finalidade e dos limites reconhecidos"),
    "189": row("A violação do direito faz nascer a pretensão, que se extingue pela prescrição nos prazos legais.", "Pretensão é o poder de exigir de outra pessoa uma prestação ou reparação. A prescrição atinge essa exigibilidade, e seus prazos gerais estão nos arts. 205 e 206, sem excluir regras especiais.", "Dívida vencida e não paga permite cobrança; o prazo prescricional começa conforme a violação e a disciplina aplicável.", "Nem todo prazo começa na data do contrato. É preciso identificar quando houve violação e se existe regra especial, impedimento, suspensão ou interrupção.", "Pretensão", "poder de exigir de alguém o cumprimento ou a reparação de um direito violado"),
    "190": row("A defesa fundada no mesmo direito prescreve no prazo correspondente à pretensão.", "A exceção, entendida como defesa material, acompanha o prazo da pretensão que poderia ter sido exercida ativamente. A regra evita uso defensivo indefinido de posição já prescrita.", "Devedor pretende opor compensação baseada em crédito cuja pretensão prescreveu; examina-se o mesmo prazo.", "O artigo trata de exceção material e não de toda defesa processual. A natureza da alegação deve ser identificada antes de aplicar prescrição.", "Exceção material", "defesa baseada em direito substantivo capaz de neutralizar a pretensão adversa"),
})

ROWS.update({
    "191": row("Só se pode renunciar à prescrição depois de consumada, expressa ou tacitamente, e sem prejudicar terceiro.", "Antes do término do prazo, a proteção legal não pode ser abandonada. Depois, o beneficiado pode deixar de invocá-la por declaração ou comportamento incompatível, desde que não afete direito alheio.", "Devedor paga voluntariamente dívida já prescrita, comportamento compatível com renúncia tácita.", "Renúncia não reabre automaticamente prazo nem pode lesar credor ou garantidor. Deve ser distinguida de reconhecimento ocorrido antes da consumação.", "Renúncia tácita", "abandono demonstrado por comportamento incompatível com a intenção de usar a prescrição"),
    "192": row("As partes não podem aumentar nem reduzir contratualmente os prazos prescricionais.", "Prescrição possui disciplina legal obrigatória quanto à duração. Cláusula privada não substitui os prazos do Código ou de lei especial.", "Contrato não pode transformar prazo prescricional legal de cinco anos em dez meses.", "As partes podem organizar cumprimento e vencimento dentro da lei, o que influencia o nascimento da pretensão; não podem alterar o prazo prescricional já definido pelo ordenamento.", "Prazo prescricional", "período legal para exercer judicialmente uma pretensão antes de sua prescrição"),
    "193": row("A parte beneficiada pode alegar prescrição em qualquer grau de jurisdição.", "A defesa não fica limitada ao primeiro momento processual, embora deva respeitar regras do procedimento, fatos já fixados e impossibilidade de inovação que exija prova indevida.", "Réu invoca prescrição ao recorrer, ainda que não a tenha apresentado na contestação.", "A expressão não autoriza reabrir processo encerrado nem ignorar preclusões sobre matéria fática. A aplicação concreta convive com a legislação processual.", "Grau de jurisdição", "etapa ou instância em que o processo é examinado por órgão judicial"),
    "195": row("Relativamente incapazes e pessoas jurídicas podem cobrar de assistentes ou representantes o prejuízo causado por deixar a prescrição ocorrer ou por não alegá-la a tempo.", "O representante que administra interesses alheios responde quando sua atuação culposa provoca perda da pretensão ou da defesa prescricional. A ação é contra quem descumpriu o dever de proteção.", "Administrador deixa vencer cobrança da pessoa jurídica sem justificativa e responde pelo dano.", "A prescrição do direito original não desaparece. Surge possível responsabilidade do representante, que exige demonstração de conduta, dano e nexo.", "Ação regressiva", "pretensão contra quem causou prejuízo ao deixar de cumprir dever de representação"),
    "196": row("Prescrição já iniciada continua correndo contra o sucessor da pessoa originalmente atingida.", "Morte, cessão ou outra sucessão não reinicia o prazo. O sucessor recebe a posição jurídica com o tempo já transcorrido.", "Herdeiro assume crédito quando metade do prazo prescricional já passou e dispõe apenas do período restante.", "Causas específicas de impedimento ou suspensão podem atuar, mas a sucessão isolada não zera a contagem.", "Sucessor", "pessoa que assume posição jurídica antes pertencente a outra"),
    "197": row("A prescrição não corre entre cônjuges durante a sociedade conjugal, entre ascendentes e descendentes durante o poder familiar, nem entre incapazes e seus tutores ou curadores durante o encargo.", "A lei suspende ou impede o prazo em relações de especial confiança e dependência, evitando que a cobrança seja exigida enquanto persiste o vínculo protegido.", "Prazo de pretensão entre tutelado e tutor não corre durante a tutela.", "A proteção depende da existência atual do vínculo indicado. Separação, fim do poder familiar ou encerramento da tutela alteram o marco de contagem.", "Impedimento da prescrição", "causa legal que evita o início do prazo enquanto determinada situação persiste"),
    "198": row("A prescrição não corre contra menores de dezesseis anos, agentes públicos ausentes do país em serviço e militares em guerra.", "As situações enumeradas protegem pessoas impedidas ou severamente limitadas para defender seus direitos. Encerrada a causa, inicia-se ou retoma-se a contagem conforme o caso.", "Pretensão pertencente a criança de doze anos não prescreve contra ela durante essa incapacidade absoluta.", "A proteção do inciso I alcança os incapazes do art. 3º, não toda incapacidade relativa. Serviço no exterior e serviço militar devem corresponder exatamente às hipóteses legais.", "Suspensão da prescrição", "paralisação temporária de prazo já iniciado por causa prevista em lei"),
    "199": row("Também não corre prescrição enquanto pende condição suspensiva, antes do vencimento ou durante ação de evicção.", "Sem direito exigível, não há razão para consumir prazo contra o titular. A condição, o termo não vencido ou a discussão de perda do bem impede a fluência nas hipóteses legais.", "Credor não perde prazo de cobrança antes de a dívida vencer.", "Condição suspensiva e termo têm regimes próprios. É preciso identificar quando a pretensão se tornou exercitável e quando cessou a causa de paralisação.", "Evicção", "perda total ou parcial de bem por direito anterior reconhecido a terceiro"),
    "200": row("Se a pretensão civil depende de fato que deve ser apurado criminalmente, a prescrição não corre antes da sentença penal definitiva.", "A regra evita que o prazo civil se esgote enquanto a definição criminal indispensável ainda está pendente. Exige relação de dependência entre a ação civil e o fato submetido ao juízo penal.", "Pedido de reparação aguarda definição penal necessária sobre autoria do fato que o fundamenta.", "A simples existência de investigação não suspende toda pretensão civil. Deve haver fato que realmente precise ser decidido no processo criminal.", "Sentença definitiva", "decisão final que não está mais sujeita aos recursos cabíveis naquela relação processual"),
    "201": row("Suspensão favorável a um credor solidário só beneficia os demais quando a obrigação é indivisível.", "Em solidariedade, causas pessoais de suspensão normalmente permanecem restritas. A indivisibilidade justifica extensão porque a prestação não pode ser separada entre credores.", "Prazo suspenso por condição pessoal de um credor não para para os outros se a prestação puder ser dividida.", "Solidariedade e indivisibilidade são institutos distintos. A extensão exige a combinação indicada pelo artigo.", "Credor solidário", "credor que pode exigir integralmente prestação comum conforme o vínculo de solidariedade"),
    "202": row("A prescrição pode ser interrompida uma única vez pelos atos legais, como citação promovida corretamente, protesto, apresentação de título, constituição judicial em mora ou reconhecimento do direito pelo devedor.", "Interrupção elimina o tempo já transcorrido e faz o prazo recomeçar da data do ato ou do último ato processual interruptivo. A lista exige correspondência com uma hipótese legal.", "Devedor reconhece inequivocamente a dívida por escrito, interrompendo a contagem.", "A interrupção civil só pode ocorrer uma vez. Propositura sem diligência exigida para citação pode não produzir o efeito pretendido.", "Interrupção", "evento que apaga o tempo prescricional transcorrido e reinicia a contagem"),
    "203": row("Qualquer pessoa juridicamente interessada pode provocar a interrupção da prescrição.", "A iniciativa não pertence apenas ao titular original da pretensão. Terceiro cuja esfera jurídica dependa da preservação do direito pode praticar ato interruptivo adequado.", "Garantidor com interesse na existência do crédito adota medida legal capaz de interromper o prazo.", "É necessário interesse jurídico real e uso de uma das causas reconhecidas. Mera preocupação econômica ou comunicação informal sem efeito legal pode não bastar.", "Interessado", "pessoa cuja posição jurídica pode ser afetada pela prescrição"),
    "204": row("Em regra, interrupção por um credor ou contra um devedor não se estende aos demais, com exceções para solidariedade, indivisibilidade e fiança.", "Entre credores e devedores solidários, o efeito pode alcançar o grupo; contra herdeiro, a extensão depende de obrigação ou direito indivisível. Interrupção contra o devedor principal prejudica o fiador.", "Cobrança interruptiva contra devedor solidário alcança os demais coobrigados nas condições do artigo.", "Não se deve generalizar o efeito coletivo. A relação precisa ser qualificada como solidariedade, indivisibilidade, sucessão ou fiança.", "Coobrigado", "pessoa vinculada com outras ao cumprimento de uma obrigação"),
    "205": row("Na ausência de prazo menor previsto em lei, a prescrição ocorre em dez anos.", "É a regra geral subsidiária. Antes de utilizá-la, devem ser pesquisados os prazos específicos do art. 206 e de legislação especial.", "Pretensão sem prazo prescricional próprio identificado submete-se, em princípio, ao período de dez anos.", "O prazo geral não se aplica por conveniência. A natureza da pretensão e a existência de norma especial precisam ser verificadas primeiro.", "Prazo geral", "prazo aplicado quando nenhuma regra específica estabelece período menor"),
    "206": row("O artigo fixa prazos especiais de um, dois, três, quatro e cinco anos para pretensões expressamente enumeradas.", "Em um ano estão, entre outras, hospedagem e alimentos consumidos no estabelecimento, emolumentos de auxiliares e peritos e créditos ligados ao encerramento de sociedade; o antigo inciso de seguro do § 1º foi revogado. Em dois anos prescrevem prestações alimentares vencidas. Em três anos entram aluguéis, rendas, juros e dividendos periódicos, enriquecimento sem causa, reparação civil, lucros de má-fé, certas responsabilidades societárias, títulos de crédito e seguro obrigatório. Em quatro anos, pretensão relativa à tutela. Em cinco anos, dívida líquida documentada, honorários profissionais e despesas judiciais do vencedor.", "Cobrança de dívida líquida constante de contrato particular sujeita-se, em regra, ao prazo de cinco anos.", "Cada prazo depende da qualificação exata da pretensão e do marco inicial próprio. O § 1º, II, está revogado desde a vigência da Lei 15.040/2024 e não deve ser usado.", "Prazo especial", "período prescricional definido para uma categoria específica de pretensão"),
    "206-A": row("A prescrição intercorrente segue o mesmo prazo da pretensão e observa impedimento, suspensão, interrupção e a disciplina processual da execução.", "Ela ocorre durante processo em que a pretensão permanece sem andamento útil nas condições legais. O prazo material aplicável é o mesmo da pretensão original, articulado com o procedimento do art. 921 do Código de Processo Civil.", "Execução permanece suspensa e, cumpridos os marcos processuais, passa a correr o prazo correspondente ao crédito.", "Não se conta automaticamente desde qualquer paralisação. Termo inicial, suspensão e intimações dependem das regras processuais aplicáveis.", "Prescrição intercorrente", "prescrição que se desenvolve durante processo paralisado nas condições previstas em lei"),
    "207": row("Regras que impedem, suspendem ou interrompem prescrição não se aplicam à decadência, salvo previsão legal contrária.", "Prescrição e decadência possuem regimes diferentes. Não se transportam automaticamente ao prazo decadencial as causas protetivas dos artigos anteriores.", "Reconhecimento de direito pelo devedor pode interromper prescrição, mas não interrompe decadência sem regra específica.", "A ressalva legal é importante: alguns artigos aplicam expressamente certas proteções à decadência, como faz o art. 208.", "Decadência", "extinção do próprio direito potestativo por falta de exercício no prazo"),
    "208": row("À decadência aplicam-se a responsabilidade do representante que causou a perda do prazo e a proteção do absolutamente incapaz.", "A lei seleciona duas regras da prescrição: ação contra assistente ou representante responsável e não fluência contra os incapazes do art. 3º. As demais causas não são incorporadas por analogia.", "Prazo decadencial não corre contra criança absolutamente incapaz, conforme a remissão legal.", "A extensão é restrita aos arts. 195 e 198, inciso I. Não inclui automaticamente serviço público no exterior, guerra ou relações familiares.", "Remissão legal", "técnica pela qual um artigo manda aplicar regra prevista em outro dispositivo"),
    "209": row("É nula a renúncia a prazo decadencial estabelecido por lei.", "Quando a própria lei fixa a decadência, o beneficiado não pode afastá-la por declaração ou comportamento. O regime protege a segurança jurídica definida pelo legislador.", "Cláusula que promete nunca invocar decadência legal é inválida.", "A regra refere-se à decadência legal. Prazo convencionado pelas partes segue disciplina diferente, respeitados os limites do negócio.", "Decadência legal", "prazo extintivo fixado diretamente por norma jurídica"),
    "210": row("O juiz deve reconhecer de ofício a decadência estabelecida em lei.", "Mesmo sem alegação da parte favorecida, o magistrado aplica o prazo legal quando seus pressupostos estão demonstrados. Isso decorre do caráter obrigatório da decadência legal.", "Documentos mostram que o prazo legal terminou, e o juiz reconhece a decadência independentemente de pedido do réu.", "As partes devem ter oportunidade de se manifestar sobre fatos e cálculo. Decadência convencional não recebe o mesmo tratamento.", "Conhecimento de ofício", "aplicação judicial de matéria que não depende de pedido da parte"),
    "211": row("Decadência criada por convenção pode ser alegada pela parte beneficiada em qualquer grau, mas não pode ser suprida pelo juiz.", "O prazo convencional protege interesse privado. Cabe ao interessado invocá-lo; o magistrado não o reconhece por iniciativa própria.", "Contrato fixa prazo decadencial válido e a parte o alega em recurso.", "A convenção deve ser válida e não pode contrariar norma obrigatória. A possibilidade de alegação convive com regras processuais sobre prova e inovação.", "Decadência convencional", "perda de direito pelo prazo validamente estipulado pelas partes"),
    "212": row("Fatos jurídicos podem ser provados por confissão, documento, testemunha, presunção e perícia, salvo exigência de forma especial.", "O rol apresenta meios gerais de prova. Quando a validade do negócio depende de forma solene, simples prova de que houve acordo não substitui o requisito legal.", "Perícia demonstra defeito técnico, enquanto documentos e testemunhas comprovam comunicações entre as partes.", "Admissibilidade, produção e valoração também seguem a legislação processual. Meio de prova não corrige negócio inválido por falta de forma essencial.", "Presunção", "inferência de um fato desconhecido a partir de fatos conhecidos e regras de experiência ou lei"),
    "213": row("Confissão só é eficaz se feita por pessoa capaz de dispor do direito; representante confessa apenas dentro de seus poderes.", "Como a confissão pode prejudicar a posição jurídica, exige capacidade e disponibilidade do direito. O representante não pode vincular o representado além da autorização recebida.", "Procurador com poderes limitados não confessa validamente fato que implique renúncia patrimonial fora do mandato.", "Confissão sobre direito indisponível ou por incapaz não ganha eficácia apenas porque foi formalizada. Devem ser conferidos capacidade e poderes.", "Confissão", "admissão de fato contrário ao interesse de quem declara e favorável à outra parte"),
    "214": row("Confissão não pode ser simplesmente retirada, mas pode ser anulada quando decorreu de erro de fato ou coação.", "A estabilidade da confissão impede arrependimento comum. A invalidação exige vício específico que comprometa a compreensão factual ou a liberdade da declaração.", "Pessoa confessa fato porque foi ameaçada e pede anulação ao demonstrar a coação.", "Erro jurídico, mudança de estratégia ou posterior discordância não equivalem automaticamente a erro de fato ou coação.", "Irrevogabilidade", "impossibilidade de desfazer unilateralmente uma declaração apenas por mudança de vontade"),
    "215": row("Escritura pública lavrada por tabelião tem fé pública e deve conter identificação, capacidade, vontade, requisitos legais, leitura, assinaturas e demais formalidades previstas.", "O instrumento documenta de forma qualificada o ato. Deve indicar data e local, partes e comparecentes, vontade clara, exigências legais e fiscais, leitura e assinaturas. Há regras para assinatura a rogo, língua portuguesa, intérprete e testemunhas de identidade.", "Pessoa que não sabe escrever participa da escritura e outra pessoa capaz assina a seu rogo, conforme a formalidade legal.", "Fé pública fortalece a prova do que foi formalizado, mas não torna verdadeiro todo fato externo nem salva objeto ilícito, incapacidade ou outro vício do negócio.", "Fé pública", "presunção qualificada de autenticidade atribuída aos atos do agente público competente"),
    "216": row("Certidões textuais e traslados judiciais extraídos e subscritos por escrivão competente fazem a mesma prova que os originais.", "A autenticidade decorre da extração sob responsabilidade do servidor e, nos traslados feitos por outro escrivão, da conferência exigida. Isso permite usar reprodução oficial sem deslocar o original.", "Parte apresenta certidão textual de peça do processo assinada pelo escrivão responsável.", "Cópia informal ou incompleta não recebe automaticamente a equivalência. Devem ser observadas extração, subscrição e conferência previstas.", "Traslado", "reprodução oficial e autenticada de documento ou peça original"),
    "217": row("Traslados e certidões emitidos por tabelião ou oficial de registro têm a mesma força probatória dos documentos registrados em suas notas.", "A reprodução oficial conserva a eficácia probatória do assento ou instrumento arquivado, desde que seja expedida pelo agente competente.", "Cartório fornece certidão de escritura existente em seus livros para uso como prova.", "A certidão prova o conteúdo registrado, mas não elimina possibilidade de discutir falsidade, vício do negócio ou inexatidão conforme os meios legais.", "Certidão", "documento oficial que reproduz ou atesta conteúdo existente em registro público"),
    "218": row("Traslados e certidões tornam-se instrumentos públicos quando os originais foram produzidos em juízo como prova de ato.", "A apresentação judicial do original e a extração oficial atribuem natureza pública à reprodução para fins probatórios.", "Original é juntado ao processo e dele se extrai certidão que passa a funcionar como instrumento público.", "O artigo não transforma qualquer cópia privada em documento público. Exige original produzido em juízo e reprodução qualificada.", "Instrumento público", "documento formado ou autenticado por agente público no exercício de sua competência"),
    "219": row("Declarações em documento assinado presumem-se verdadeiras contra os signatários; afirmações acessórias podem exigir prova adicional.", "A assinatura vincula a pessoa ao conteúdo declaratório principal. Informações meramente enunciativas, sem relação direta com o negócio ou legitimidade, não dispensam quem as invoca de demonstrar sua veracidade.", "Recibo assinado presume o pagamento declarado, mas comentário lateral sobre fato estranho pode exigir outra prova.", "A presunção admite contestação pelos meios legais e não se estende indistintamente a todo dado mencionado no documento.", "Declaração enunciativa", "afirmação acessória que apenas relata fato sem integrar diretamente a disposição principal"),
    "220": row("Consentimento ou autorização necessários à validade devem ser provados pela mesma forma do ato e, quando possível, constar do próprio instrumento.", "A exigência de simetria evita que autorização informal sustente negócio sujeito a forma qualificada. Reunir a anuência no documento principal melhora segurança e prova.", "Se o negócio exige escritura pública e depende de autorização, a anuência deve observar a mesma forma.", "Quando a lei não exige autorização ou forma especial, a regra não cria solenidade desnecessária. Deve-se identificar o requisito do ato principal.", "Anuência", "consentimento de pessoa cuja concordância é necessária para validade do ato"),
    "221": row("Instrumento particular assinado por quem administra livremente seus bens prova obrigações convencionais de qualquer valor, mas só produz efeitos contra terceiros após registro público.", "Entre os signatários, o documento particular comprova a obrigação independentemente do valor. Para torná-la oponível a terceiros, inclusive na cessão, é necessário o registro; se o instrumento faltar, outros meios legais ainda podem demonstrá-lo.", "Duas pessoas assinam contrato particular de dívida; ele as vincula, mas a cessão só pode ser oposta a terceiro depois do registro exigido.", "Eficácia entre as partes não se confunde com eficácia perante terceiros. O parágrafo único admite suprimento probatório, não dispensa forma exigida para a validade do negócio.", "Oponibilidade", "possibilidade de fazer um ato ou direito produzir efeitos contra terceiros"),
    "222": row("Se a autenticidade de telegrama for contestada, ele prova seu conteúdo mediante conferência com o original assinado.", "A impugnação não elimina automaticamente o valor do telegrama. Exige-se comparar a mensagem transmitida com o documento original que contém a assinatura do remetente.", "Destinatário apresenta telegrama e, após contestação, o conteúdo é conferido com o formulário original assinado.", "Sem contestação, a conferência não é imposta por este artigo. Havendo impugnação, mera reprodução desacompanhada do original não resolve a autenticidade.", "Conferência", "comparação destinada a confirmar que uma reprodução corresponde ao original"),
    "223": row("Cópia fotográfica conferida por tabelião prova declaração de vontade, mas o original deve ser exibido se a autenticidade for impugnada.", "A autenticação notarial dá força probatória à cópia, sujeita à apresentação do documento original quando houver contestação. Ela não substitui título ou original cuja exibição seja condição para exercer o direito.", "Uma cópia autenticada de contrato é aceita; diante de impugnação específica, a parte apresenta o original.", "Autenticação de cópia não cria o documento nem supre título de crédito ausente. A necessidade do original pode decorrer da lei ou das circunstâncias.", "Cópia autenticada", "reprodução cuja correspondência com o original foi certificada por agente competente"),
    "224": row("Documento redigido em língua estrangeira deve ser traduzido para o português para produzir efeitos legais no Brasil.", "A tradução torna o conteúdo juridicamente utilizável no País e permite que autoridades e partes conheçam seu sentido. Regras especiais definem quando se exige tradução pública ou outra formalidade.", "Contrato escrito em alemão é acompanhado de tradução para ser apresentado em procedimento brasileiro.", "O artigo não decide sozinho quem pode traduzir nem valida o negócio estrangeiro; essas questões dependem da legislação aplicável e da finalidade do documento.", "Tradução pública", "tradução feita por profissional habilitado quando a lei exige fé pública"),
    "225": row("Reproduções fotográficas, audiovisuais, sonoras, mecânicas ou eletrônicas fazem prova plena do fato ou da coisa se a parte contrária não impugnar sua exatidão.", "Fotos, gravações e outros registros podem demonstrar diretamente o que reproduzem. A ausência de impugnação específica fortalece sua eficácia; contestação abre a necessidade de verificar autenticidade, integridade e contexto.", "Gravação de entrega é juntada ao processo e a outra parte não questiona sua exatidão.", "Prova plena não significa verdade absoluta nem dispensa análise de licitude e contexto. Se houver impugnação, perícia ou outros elementos podem ser necessários.", "Exatidão", "correspondência fiel entre a reprodução apresentada e o fato ou objeto registrado"),
    "226": row("Livros e fichas empresariais provam contra seu titular e também a seu favor quando regulares e confirmados por outros elementos.", "A escrituração pode prejudicar o empresário pelo que registra. Para favorecê-lo, precisa estar sem vícios internos ou externos e receber confirmação independente; jamais substitui forma especial exigida por lei.", "Lançamentos contábeis regulares, confirmados por notas fiscais, ajudam a provar crédito da sociedade.", "Os registros podem ser afastados por prova de falsidade ou inexatidão. Sozinhos, não suprem escritura pública nem escrito sujeito a requisitos especiais.", "Vício intrínseco", "defeito no conteúdo ou na coerência interna da escrituração"),
    "227": row("A prova testemunhal é admitida como complemento ou apoio da prova escrita, qualquer que seja o valor do negócio.", "Embora o caput tenha sido revogado, o parágrafo único permanece vigente. Testemunhas podem esclarecer ou completar documento já existente sem limite baseado no valor econômico do negócio.", "Mensagens documentam parcialmente um acordo e testemunha esclarece como a entrega foi combinada.", "O dispositivo preservado trata de prova subsidiária ou complementar; não afirma que testemunho sempre substitui documento ou forma solene exigida por lei.", "Prova subsidiária", "prova usada como apoio de outro elemento probatório principal", target="CC2002:ART.227:PAR.UNICO"),
    "228": row("Em regra, não são admitidos como testemunhas menores de dezesseis anos, interessados, amigos íntimos, inimigos capitais e certos parentes das partes; há exceções e garantia de acessibilidade à pessoa com deficiência.", "A norma busca confiabilidade e imparcialidade, mas permite ao juiz ouvir pessoas impedidas quando somente elas conhecem os fatos. Pessoa com deficiência testemunha em igualdade, com tecnologia assistiva. Os incisos II e III estão revogados.", "Parente que presenciou fato conhecido apenas pela família pode ser ouvido por decisão do juiz.", "As restrições não autorizam exclusão automática da pessoa com deficiência. O juiz deve distinguir impedimento, exceção do § 1º e valoração do depoimento no caso concreto.", "Tecnologia assistiva", "recursos e serviços que promovem autonomia e participação da pessoa com deficiência"),
    "231": row("Quem se recusa a exame médico necessário não pode obter vantagem jurídica decorrente da própria recusa.", "A parte não pode bloquear a produção de elemento relevante e depois usar a falta do exame em seu favor. A consequência concreta depende da necessidade, legitimidade e proporcionalidade da medida.", "Pessoa impede exame necessário para esclarecer filiação e depois pretende beneficiar-se da incerteza que criou.", "A regra não autoriza coerção física nem torna todo exame obrigatório. Devem ser respeitados direitos fundamentais e avaliadas justificativas para a recusa.", "Recusa", "não submissão voluntária ao exame considerado necessário para esclarecer fato relevante"),
    "232": row("A recusa a perícia médica ordenada pelo juiz pode suprir a prova que o exame buscava produzir.", "O magistrado pode extrair consequência probatória da recusa e considerar demonstrado o fato que dependia da perícia, em conjunto com as circunstâncias do processo.", "Em investigação de filiação, a recusa injustificada ao exame é valorada com os demais elementos para suprir a prova pretendida.", "A palavra 'poderá' indica que o efeito não é mecânico. Ordem válida, pertinência do exame, justificativa e conjunto probatório precisam ser examinados.", "Suprir a prova", "permitir que outro elemento ou comportamento ocupe a função probatória do exame não realizado"),
    "233": row("A obrigação de entregar coisa certa inclui seus acessórios, mesmo não mencionados, salvo disposição do título ou circunstâncias em contrário.", "O bem individualizado deve ser entregue com os elementos que normalmente o acompanham. As partes ou o contexto podem excluir determinado acessório.", "A venda de máquina específica abrange seus componentes usuais, salvo cláusula que reserve peça destacável.", "É preciso distinguir acessório, fruto, benfeitoria e bem autônomo. A regra cede ao contrato e às circunstâncias comprovadas.", "Coisa certa", "bem individualizado e identificado como objeto específico da obrigação"),
    "234": row("Se a coisa certa se perde sem culpa do devedor antes da entrega ou durante condição suspensiva, a obrigação se resolve; com culpa, ele deve o equivalente e perdas e danos.", "Antes da tradição, o risco da perda fortuita permanece com o devedor e extingue as prestações recíprocas. Se ele causou a perda, substitui o bem pelo valor correspondente e indeniza prejuízos adicionais.", "Obra única é destruída por raio antes da entrega: o negócio se resolve; se foi destruída por negligência do devedor, há indenização.", "A consequência depende de perda total, momento, culpa e eventual mora. Deterioração parcial segue os artigos seguintes.", "Tradição", "ato de entrega que transfere a posse e, em regra, a propriedade de bem móvel"),
    "235": row("Se a coisa certa se deteriora sem culpa do devedor, o credor pode resolver a obrigação ou recebê-la com abatimento proporcional do preço.", "A perda parcial fortuita oferece escolha ao credor: desfazer a relação ou conservar o negócio pagando menos conforme a desvalorização.", "Equipamento sofre dano fortuito antes da entrega; o comprador cancela a compra ou aceita o bem com redução do preço.", "O credor não recebe simultaneamente resolução e coisa abatida. Se houve culpa do devedor, aplica-se o regime mais gravoso do art. 236.", "Deterioração", "redução de valor ou utilidade sem desaparecimento completo da coisa"),
    "236": row("Se o devedor causa a deterioração da coisa certa, o credor pode exigir o equivalente ou aceitar o bem como está, sempre com direito a perdas e danos.", "A culpa amplia a proteção do credor: qualquer das alternativas principais pode ser acompanhada de indenização pelos prejuízos causados.", "Devedor danifica veículo prometido; o credor exige valor equivalente e indenização ou recebe o veículo e cobra os danos.", "Perdas e danos exigem demonstração e nexo causal. A escolha não permite duplicidade de reparação pelo mesmo prejuízo.", "Equivalente", "valor ou prestação que substitui economicamente a coisa devida"),
    "237": row("Até a entrega, melhoramentos e acréscimos pertencem ao devedor, que pode pedir aumento do preço; sem concordância do credor, pode resolver a obrigação.", "Como a coisa ainda pertence ao devedor, sua valorização natural ou superveniente pode justificar revisão do preço. Se não houver acordo, o devedor pode desfazer a obrigação. Frutos colhidos ficam com ele; os pendentes, com o credor.", "Animal vendido gera cria antes da entrega; as partes avaliam o acréscimo e, sem acordo sobre preço, o devedor pode resolver o negócio.", "A regra não autoriza aumento unilateral consumado. É necessário distinguir frutos já percebidos dos ainda ligados à coisa.", "Frutos pendentes", "utilidades produzidas pela coisa que ainda não foram separadas dela"),
    "238": row("Na restituição de coisa certa, sua perda sem culpa do devedor antes da entrega é suportada pelo credor, resolvendo-se a obrigação e preservando-se direitos anteriores à perda.", "Quem tem direito à devolução também suporta o risco fortuito da coisa que lhe pertence. A restituição se torna impossível, mas créditos e efeitos constituídos até a perda permanecem.", "Bem emprestado é destruído por evento inevitável sem culpa de quem devia devolvê-lo; não há equivalente, sem prejuízo de obrigações anteriores.", "Este artigo trata de restituir, não de dar coisa para transferir propriedade. Culpa do devedor conduz ao art. 239.", "Obrigação de restituir", "dever de devolver ao titular a própria coisa anteriormente recebida"),
    "239": row("Se a coisa a restituir se perde por culpa do devedor, ele responde pelo equivalente e por perdas e danos.", "A impossibilidade causada por quem devia devolver não extingue sua responsabilidade. Ele paga o valor da coisa e repara prejuízos adicionais ligados à perda.", "Depositário destrói culposamente o bem guardado e deve pagar seu valor e os danos comprovados.", "O equivalente não absorve necessariamente outros prejuízos, mas a reparação não pode duplicar a mesma perda.", "Perdas e danos", "indenização dos prejuízos patrimoniais ligados ao inadimplemento"),
    "240": row("Se a coisa a restituir se deteriora sem culpa, o credor a recebe no estado em que está, sem indenização; havendo culpa, aplica-se a responsabilidade por equivalente e perdas e danos.", "Na restituição, o titular suporta a deterioração fortuita de sua coisa. Quando o devedor causou o dano, incide o regime do art. 239, adaptado à deterioração.", "Objeto guardado sofre desgaste inevitável e é devolvido como está; se houve mau uso culposo, nasce responsabilidade.", "É essencial apurar culpa, desgaste normal e extensão do dano. A remissão ao art. 239 não transforma automaticamente dano parcial em perda total.", "Deterioração fortuita", "redução do estado da coisa causada sem culpa de quem devia devolvê-la"),
    "241": row("Melhoramento ou acréscimo da coisa a restituir, ocorrido sem trabalho ou despesa do devedor, beneficia o credor sem indenização.", "A valorização natural ou independente do devedor acompanha o bem de seu titular. Quem o restitui não pode cobrar por vantagem que não produziu nem custeou.", "Terreno a devolver valoriza-se por obra pública vizinha; o proprietário recebe o acréscimo sem pagar ao detentor.", "Se houve trabalho ou gasto do devedor, aplica-se o art. 242, e não esta regra de gratuidade.", "Acréscimo", "aumento físico, econômico ou útil incorporado à coisa"),
    "242": row("Melhoramentos feitos com trabalho ou despesa do devedor e frutos percebidos seguem as regras das benfeitorias e frutos do possuidor de boa-fé ou de má-fé.", "O direito a indenização, retenção ou restituição depende da natureza da melhoria e da boa ou má-fé de quem detinha a coisa. O mesmo critério define o tratamento dos frutos já colhidos.", "Quem devia devolver imóvel realiza obra útil; sua indenização é avaliada conforme as normas aplicáveis ao possuidor e sua boa-fé.", "Não há direito automático ao reembolso integral. É preciso classificar benfeitoria, frutos e estado subjetivo do devedor.", "Benfeitoria", "obra ou despesa realizada para conservar, melhorar ou embelezar uma coisa"),
    "243": row("Coisa incerta deve ser indicada ao menos pelo gênero e pela quantidade.", "A obrigação pode começar sem individualizar cada unidade, mas precisa fornecer critérios mínimos que tornem a prestação determinável.", "Contrato prevê entrega de cem sacas de café de gênero indicado, deixando a separação das unidades para depois.", "Descrição excessivamente vaga pode tornar o objeto indeterminável. Qualidade, escolha e concentração são disciplinadas pelos artigos seguintes e pelo título.", "Coisa incerta", "prestação definida por características gerais, ainda sem individualização das unidades"),
    "244": row("Na obrigação definida por gênero e quantidade, a escolha cabe ao devedor salvo disposição contrária; ele não pode entregar a pior coisa nem é obrigado a dar a melhor.", "Quem escolhe deve selecionar qualidade média compatível com o gênero. O contrato pode transferir a escolha ao credor ou fixar critério mais específico.", "Devedor escolhe cem unidades dentro do estoque, mas não pode separar apenas as defeituosas.", "A margem de escolha não autoriza prestação inferior ao padrão devido. Usos, boa-fé e especificações contratuais também orientam a qualidade.", "Concentração", "ato de individualizar os bens que cumprirão uma obrigação inicialmente genérica"),
    "245": row("Depois de cientificado o credor sobre a escolha, aplicam-se as regras da obrigação de dar coisa certa.", "A comunicação válida concentra a obrigação: os bens escolhidos tornam-se individualizados e passam ao regime de perda, deterioração, melhoramentos e entrega da seção anterior.", "Fornecedor separa as unidades devidas e informa formalmente o comprador; a prestação passa a recair sobre aqueles bens.", "Separação interna não basta necessariamente: o artigo exige ciência do credor. A escolha também deve respeitar o título e a qualidade legal.", "Cientificação", "comunicação que dá conhecimento juridicamente relevante à outra parte"),
    "246": row("Antes da escolha, o devedor não pode alegar perda ou deterioração da coisa genérica, nem mesmo por caso fortuito ou força maior.", "Enquanto o gênero ainda permite obter outras unidades, a destruição do estoque inicialmente pensado não libera o devedor. A obrigação permanece possível até a concentração válida.", "Incêndio destrói as sacas que o devedor pretendia entregar, mas ele deve obter outras do mesmo gênero e quantidade.", "A regra pressupõe que o gênero continue existente e que a obrigação não tenha sido validamente limitada a conjunto específico.", "Gênero não perece", "ideia de que a perda de unidades não extingue obrigação ainda cumprível com outras do mesmo gênero"),
    "247": row("Devedor que recusa prestação de fazer pessoalíssima ou executável somente por ele deve indenizar perdas e danos.", "Quando a atividade depende das qualidades ou da atuação exclusiva do devedor, terceiro não pode substituí-lo. A recusa converte o inadimplemento em responsabilidade indenizatória.", "Artista contratado para obra pessoal se recusa a realizá-la e responde pelos prejuízos causados.", "A indenização depende de recusa e dano; impossibilidade sem culpa segue o art. 248. Também deve ser verificado se a prestação era realmente infungível.", "Prestação infungível", "obrigação que, por sua natureza ou pelo contrato, só pode ser cumprida pelo próprio devedor"),
    "248": row("Se a prestação de fazer se torna impossível sem culpa do devedor, a obrigação se resolve; se a impossibilidade decorre de culpa, há perdas e danos.", "A impossibilidade superveniente fortuita extingue o dever sem indenização. Se o devedor causou o impedimento, responde pelos prejuízos do inadimplemento.", "Apresentação personalíssima se torna impossível por evento inevitável; se o contratado provocou deliberadamente a impossibilidade, indeniza.", "Dificuldade ou maior custo não equivalem automaticamente a impossibilidade. Devem ser examinados culpa, mora e momento do impedimento.", "Impossibilidade superveniente", "impedimento surgido depois da obrigação que torna inviável cumprir a prestação"),
    "249": row("Se terceiro puder executar o fato, o credor pode mandar fazê-lo à custa do devedor em recusa ou mora, além de pedir indenização; em urgência, dispensa autorização judicial prévia.", "Nas obrigações fungíveis, o credor pode obter o resultado por substituição e cobrar o custo do inadimplente. A urgência permite agir imediatamente e buscar ressarcimento depois.", "Empreiteiro atrasa reparo urgente; o credor contrata outro profissional e cobra custo razoável e prejuízos.", "Sem urgência, devem ser observados os meios jurídicos adequados. Mesmo no caso urgente, necessidade, proporcionalidade, custos e mora precisam ser demonstrados.", "Execução por terceiro", "cumprimento substitutivo da prestação por pessoa diversa do devedor original"),
    "250": row("A obrigação de não fazer se extingue quando, sem culpa do devedor, torna-se impossível abster-se do ato proibido.", "Se evento inevitável obriga o devedor a praticar o comportamento que prometera evitar, desaparece o dever de abstenção sem responsabilidade por culpa.", "Mudança legal obrigatória força empresa a realizar ato que contratualmente havia prometido não praticar.", "A extinção exige impossibilidade real e ausência de culpa. Conveniência, escolha voluntária ou criação do impedimento pelo próprio devedor não bastam.", "Obrigação de não fazer", "dever contratual ou legal de se abster de determinado comportamento"),
})


